	PADDD ·chacha20Constants<>+0(SB), X0
	PADDD ·chacha20Constants<>+0(SB), X1
	PADDD ·chacha20Constants<>+0(SB), X2
	PADDD ·chacha20Constants<>+0(SB), X12
