	PADDD 32(BP), X4
	PADDD 32(BP), X5
	PADDD 32(BP), X13
	PADDD 48(BP), X6
	PADDD 48(BP), X7
	PADDD 48(BP), X8
	PADDD 48(BP), X14
	PADDD 80(BP), X9
	PADDD 96(BP), X10
	PADDD 112(BP), X11
	PADDD 128(BP), X15

	// Load - xor - store
	MOVO  X15, 64(BP)
	MOVOU (SI), X15
	PXOR  X15, X0
	MOVOU X0, (DI)
	MOVOU 16(SI), X15
	PXOR  X15, X3
	MOVOU X3, 16(DI)
	MOVOU 32(SI), X15
	PXOR  X15, X6
	MOVOU X6, 32(DI)
	MOVOU 48(SI), X15
	PXOR  X15, X9
	MOVOU X9, 48(DI)
	MOVOU 64(SI), X9
	PXOR  X9, X1
	MOVOU X1, 64(DI)
	MOVOU 80(SI), X9
	PXOR  X9, X4
	MOVOU X4, 80(DI)
	MOVOU 96(SI), X9
	PXOR  X9, X7
	MOVOU X7, 96(DI)
	MOVOU 112(SI), X9
	PXOR  X9, X10
	MOVOU X10, 112(DI)
	MOVOU 128(SI), X9
	PXOR  X9, X2
	MOVOU X2, 128(DI)
	MOVOU 144(SI), X9
	PXOR  X9, X5
	MOVOU X5, 144(DI)
	MOVOU 160(SI), X9
	PXOR  X9, X8
	MOVOU X8, 160(DI)
	MOVOU 176(SI), X9
	PXOR  X9, X11
	MOVOU X11, 176(DI)
	MOVOU 192(SI), X9
	PXOR  X9, X12
	MOVOU X12, 192(DI)
	MOVOU 208(SI), X9
	PXOR  X9, X13
	MOVOU X13, 208(DI)
	MOVOU 224(SI), X9
	PXOR  X9, X14
	MOVOU X14, 224(DI)
	MOVOU 240(SI), X9
