	PXOR  X12, X0
	PXOR  X13, X3
	PXOR  X14, X6
	PXOR  X15, X9
	MOVOU X0, (DI)
	MOVOU X3, 16(DI)
	MOVOU X6, 32(DI)
	MOVOU X9, 48(DI)
	MOVOU 64(SI), X12
	MOVOU 80(SI), X13
	MOVOU 96(SI), X14
	MOVOU 112(SI), X15
	PXOR  X12, X1
	PXOR  X13, X4
	PXOR  X14, X7
	PXOR  X15, X10
	MOVOU X1, 64(DI)
	MOVOU X4, 80(DI)
	MOVOU X7, 96(DI)
	MOVOU X10, 112(DI)
	MOVO  X2, X1
	MOVO  X5, X4
	MOVO  X8, X7
	MOVO  X11, X10
	MOVQ  $0x00000080, CX
	LEAQ  128(SI), SI
	SUBQ  $0x80, BX
	JMP   sealSSE128SealHash

sealSSE128:
	MOVOU ·chacha20Constants<>+0(SB), X0
	MOVOU 16(R8), X3
	MOVOU 32(R8), X6
	MOVOU 48(R8), X9
	MOVO  X0, X1
	MOVO  X3, X4
	MOVO  X6, X7
	MOVO  X9, X10
	PADDL ·sseIncMask<>+0(SB), X10
	MOVO  X1, X2
	MOVO  X4, X5
	MOVO  X7, X8
	MOVO  X10, X11
	PADDL ·sseIncMask<>+0(SB), X11
	MOVO  X3, X13
	MOVO  X6, X14
	MOVO  X10, X15
	MOVQ  $0x0000000a, R9

sealSSE128InnerCipherLoop:
	PADDD X3, X0
	PXOR  X0, X9
	ROL16(X9, X12)
	PADDD X9, X6
	PXOR  X6, X3
	MOVO  X3, X12
	PSLLL $0x0c, X12
	PSRLL $0x14, X3
	PXOR  X12, X3
