	ROL16(X11, X12)
	PADDD X11, X8
	PXOR  X8, X5
	MOVO  X5, X12
	PSLLL $0x0c, X12
	PSRLL $0x14, X5
	PXOR  X12, X5
	PADDD X5, X2
